const rows = $input.all().map((item) => item.json);
const slug = (value) => String(value)
  .toLowerCase()
  .replace(/ä/g, 'ae')
  .replace(/ö/g, 'oe')
  .replace(/ü/g, 'ue')
  .replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
const ipads = {};
for (const row of rows.filter((entry) => entry.group_key)) {
  if (!ipads[row.group_key]) ipads[row.group_key] = { name: row.group_name, serial: [], ntfyTopic: row.ntfy_topic || '' };
  if (row.serial_number) ipads[row.group_key].serial.push(row.serial_number);
}
for (const row of rows.filter((entry) => entry.serial_number && entry.ipad_name)) {
  const key = slug(row.ipad_name);
  if (!ipads[key]) ipads[key] = { name: row.ipad_name, serial: [row.serial_number], ntfyTopic: row.ntfy_topic || '' };
}
const ipadsError = rows.some((row) => row.error) ? 'Die iPad-Liste (automation.ipad) ist in der Datenbank nicht lesbar.' : '';
const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  depserverUrl: 'http://mdm-depserver.mdm.svc.cluster.local:9001',
  scepUrl: 'http://mdm-scep.mdm.svc.cluster.local:8080',
  publicHost: 'mdm-prod.pke-lab.de',
  depName: 'capulus',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  vmUrl: 'http://vmsingle-monitoring-victoria-metrics-k8s-stack.monitoring.svc.cluster.local:8428',
  n8nUrl: 'https://n8n.prod.homeserver',
  ipads,
  ipadsError
};
return [{ json: cfg }];

const input = $('Formular App').first().json;
const cfg = $('Konfiguration').first().json;
const choice = String(input['App'] || '');
const idField = String(input['App-Store-ID oder Link (nur bei Andere App)'] || '').trim();
const ipadChoice = String(input['iPads'] || '').trim();
const uninstall = String(input['Aktion'] || '') === 'Deinstallieren';
const serial = String(input['Seriennummer (nur bei Einzelnes iPad)'] || '').trim();
const fail = (text) => [{ json: { ok: false, title: uninstall ? 'Nichts deinstalliert' : 'Nichts installiert', message: text } }];
const norm = (value) => String(value)
  .toLowerCase()
  .replace(/ä/g, 'ae')
  .replace(/ö/g, 'oe')
  .replace(/ü/g, 'ue')
  .replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
if (uninstall && choice === 'Alle Apps der Liste') return fail('Alle Apps der Liste kann nicht auf einmal deinstalliert werden. Bitte eine einzelne App waehlen.');
let alle = false;
let serials = [];
let target = '';
if (ipadChoice === 'Alle iPads') {
  alle = true;
  target = 'alle iPads';
} else if (ipadChoice.indexOf('Einzelnes iPad') === 0) {
  if (serial.length === 0 || serial.length > 40 || !/^[A-Za-z0-9]+$/.test(serial)) return fail('Bitte die Seriennummer eintragen (nur Buchstaben und Ziffern).');
  serials = [serial];
  target = serial;
} else {
  const group = Object.values(cfg.ipads).find((entry) => norm(entry.name) === norm(ipadChoice));
  if (!group) return fail(cfg.ipadsError || 'Bitte unter iPads eine Auswahl treffen.');
  serials = [].concat(group.serial);
  if (serials.length === 0) return fail('Fuer ' + group.name + ' ist in der Datenbank (automation.ipad) noch kein iPad eingetragen.');
  target = group.name;
}
const web = {
  'Web: ISC': ['webclip-isc'],
  'Web: Lists Gruppe 1 Stunde 1': ['webclip-g1s1'],
  'Web: Lists Gruppe 1 Stunde 2': ['webclip-g1s2'],
  'Web: Lists Gruppe 2 Stunde 1': ['webclip-g2s1'],
  'Web: Lists Gruppe 2 Stunde 2': ['webclip-g2s2'],
  'Web: Alle Web-Links': ['webclip-isc', 'webclip-g1s1', 'webclip-g1s2', 'webclip-g2s1', 'webclip-g2s2']
};
if (web[choice]) return [{ json: { ok: true, mode: 'webclip', profiles: web[choice], alle, serials, target, uninstall } }];
if (choice === 'Andere App (ID unten)') {
  const match = /(?:id)?(\d{6,12})/.exec(idField);
  if (!match) return fail('Bitte die App-Store-ID (Ziffern) oder den App-Store-Link eintragen.');
  return [{ json: { ok: true, mode: 'other', adamId: match[1], alle, serials, target, uninstall } }];
}
if (choice === 'Alle Apps der Liste') return [{ json: { ok: true, mode: 'all', alle, serials, target, uninstall } }];
return [{ json: { ok: true, mode: 'one', appName: choice, alle, serials, target, uninstall } }];

const adamId = $('Eingabe pruefen').first().json.adamId;
const res = $input.first().json;
const raw = res.data !== undefined ? res.data : res.body;
let body = {};
try {
  body = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
} catch (e) {
  body = {};
}
const hit = (body.results || [])[0];
const fail = (text) => [{ json: { ok: false, title: 'Nichts installiert', message: text } }];
if (!hit) return fail('Im App Store (Deutschland) gibt es keine App mit der ID ' + adamId + '.');
if (hit.kind !== 'software' || !hit.bundleId) return fail('Die ID ' + adamId + ' ist keine iOS-App.');
if (!(hit.supportedDevices || []).some((device) => /iPad/.test(device))) return fail(hit.trackName + ' laeuft nicht auf iPads.');
if (Number(hit.price) > 0) return fail(hit.trackName + ' kostet Geld (' + hit.formattedPrice + '). Bezahlte Apps muessen in Apple Business gekauft werden, dieser Workflow installiert nur kostenlose Apps.');
return [{ json: { ok: true, adamId: String(hit.trackId), name: hit.trackName, bundleId: hit.bundleId } }];

const input = $('Eingabe pruefen').first().json;
const catalog = $input.all().map((item) => item.json).filter((row) => row.adam_id);
let apps = catalog;
if (input.mode === 'one') apps = catalog.filter((row) => row.name === input.appName);
if (input.mode === 'other') apps = catalog.filter((row) => row.adam_id === input.adamId);
if (apps.length === 0) return [{ json: { ok: false, title: 'Nichts installiert', message: 'Die App steht nicht in der Liste.' } }];
return [{ json: { ok: true, apps: apps.map((row) => ({ adamId: row.adam_id, name: row.name, bundleId: row.bundle_id, config: typeof row.config === 'string' ? JSON.parse(row.config) : (row.config || {}) })) } }];

const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (devices.length === 0) return [{ json: { skip: true } }];
return [{ json: { skip: false, serials: devices.map((row) => row.serial_number).filter(Boolean) } }];

const apps = $('Auswahl bestimmen').first().json.apps;
const serials = $('Lizenzdaten bauen').first().json.serials;
const res = $input.first().json;
const body = typeof res.body === 'string' ? JSON.parse(res.body || '{}') : (res.body || {});
const known = new Set((body.assets || []).map((asset) => String(asset.adamId)));
if (res.statusCode !== 200) {
  return [{ json: { skip: true, title: 'Nichts installiert', message: 'Die Lizenzliste bei Apple ist nicht abrufbar (HTTP ' + (res.statusCode || res.error || 'keine Antwort') + (body.errorMessage ? ', ' + body.errorMessage : '') + '). Ist das Credential Apple Apps Token gueltig?' } }];
}
const licensed = apps.filter((app) => known.has(app.adamId));
const missing = apps.filter((app) => !known.has(app.adamId));
if (licensed.length === 0) {
  return [{ json: { skip: true, title: 'Nichts installiert', message: 'Diese App ist in Apple Business nicht fuer den Standort abgerufen: ' + missing.map((app) => app.name + ' (ID ' + app.adamId + ')').join(', ') + '. Unter Apps und Buecher abrufen, dann erneut versuchen.' } }];
}
return [{ json: { skip: false, licensed, missing, body: JSON.stringify({ assets: licensed.map((app) => ({ adamId: app.adamId, pricingParam: 'STDQ' })), serialNumbers: serials }) } }];

const crypto = require('crypto');
const apps = $('Lizenzen pruefen').first().json.licensed;
const devices = $('Geraete suchen').all().map((item) => item.json).filter((row) => row.enrollment_id);
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const configXml = (config) => {
  const keys = Object.keys(config || {});
  if (keys.length === 0) return '';
  let xml = '\t\t<key>Configuration</key>\n\t\t<dict>\n';
  for (const key of keys) {
    const value = config[key];
    xml += '\t\t\t<key>' + escapeXml(key) + '</key>\n';
    if (typeof value === 'boolean') xml += '\t\t\t' + (value ? '<true/>' : '<false/>') + '\n';
    else if (typeof value === 'number') xml += '\t\t\t<integer>' + value + '</integer>\n';
    else xml += '\t\t\t<string>' + escapeXml(value) + '</string>\n';
  }
  return xml + '\t\t</dict>\n';
};
const out = [];
for (const device of devices) {
  for (const app of apps) {
    const commandUuid = crypto.randomUUID();
    const plist = '<?xml version="1.0" encoding="UTF-8"?>\n'
      + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
      + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n'
      + configXml(app.config)
      + '\t\t<key>ChangeManagementState</key>\n\t\t<string>Managed</string>\n'
      + '\t\t<key>Options</key>\n\t\t<dict>\n\t\t\t<key>PurchaseMethod</key>\n\t\t\t<integer>1</integer>\n\t\t</dict>\n'
      + '\t\t<key>RequestType</key>\n\t\t<string>InstallApplication</string>\n'
      + '\t\t<key>iTunesStoreID</key>\n\t\t<integer>' + Number(app.adamId) + '</integer>\n'
      + '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
    out.push({ json: { enrollment_id: device.enrollment_id, serial_number: device.serial_number, app: app.name, command_uuid: commandUuid, plist } });
  }
}
return out;

const license = $('Lizenz zuweisen').first().json;
const check = $('Lizenzen pruefen').first().json;
const apps = check.licensed;
const sent = $('Befehle bauen').all().map((item) => item.json);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number || source.enrollment_id, app: source.app, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const ok = results.filter((row) => row.queued);
const failed = results.filter((row) => !row.queued);
const lines = [];
const licenseBody = license.body || {};
const names = apps.map((app) => app.name).join(', ');
if (license.statusCode === 200) {
  lines.push('Lizenz fuer ' + names + ' wurde zugewiesen.');
} else {
  lines.push('ACHTUNG: Die Lizenzzuweisung bei Apple schlug fehl (HTTP ' + (license.statusCode || license.error || 'keine Antwort') + (licenseBody.errorMessage ? ', ' + licenseBody.errorMessage : '') + '). Ohne Lizenz kann ein iPad ohne Apple-ID die App nicht installieren.');
}
lines.push(ok.length + ' von ' + results.length + ' Installationsbefehl(en) eingereiht.');
if (check.missing.length > 0) lines.push('Nicht in Apple Business abgerufen und uebersprungen: ' + check.missing.map((app) => app.name).join(', ') + '.');
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.app + ' (' + row.detail + ')').join(', ') + '.');
const good = license.statusCode === 200 && failed.length === 0 && check.missing.length === 0;
return [{ json: { good, names, text: lines.join(' ') } }];

const sent = $('Liste Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
return $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const results = Object.values(body.status || {});
  const pushError = results.map((entry) => entry.push_error).filter(Boolean).join('; ');
  const detail = queued ? pushError : String(response.json.statusCode || response.json.error || 'keine Antwort');
  return { json: { enrollment_id: source.enrollment_id, profile_name: source.profile_name, command_uuid: source.command_uuid, ok: queued ? 'yes' : 'no', detail } };
});

const install = $('Ergebnis auswerten').first().json;
let listLine = 'Die Erlaubt-Liste ist unveraendert.';
const sentRows = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
if (sentRows.length > 0) {
  const failed = sentRows.filter((row) => row.state === 'failed');
  listLine = 'Die Erlaubt-Liste wurde an ' + (sentRows.length - failed.length) + ' von ' + sentRows.length + ' iPad(s) gesendet' + (failed.length > 0 ? ', ' + failed.length + ' fehlgeschlagen' : '') + '.';
}
return [{ json: { title: install.good ? install.names + ' wird installiert' : 'Installation mit Problemen: ' + install.names, message: install.text + ' ' + listLine + ' Die Liste greift nur auf beaufsichtigten iPads.', priority: install.good ? 'default' : 'high' } }];

const crypto = require('crypto');
const input = $('Eingabe pruefen').first().json;
const profiles = $('Web-Link Profil lesen').all().map((item) => item.json).filter((row) => row.name);
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
const skip = (message) => [{ json: { skip: true, title: 'Nichts installiert', message } }];
if (devices.length === 0) return skip(input.alle ? 'Es ist noch kein iPad angemeldet.' : 'Keines der gewaehlten iPads ist angemeldet: ' + input.target + '.');
if (profiles.length !== input.profiles.length) return skip('Das Profil fuer den Web-Link fehlt in der Datenbank (automation.profile_state).');
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const out = [];
for (const device of devices) {
  for (const row of profiles) {
    const params = typeof row.params === 'string' ? JSON.parse(row.params) : row.params;
    let profile = row.template;
    for (const [key, value] of Object.entries(params)) profile = profile.split('__' + key + '__').join(escapeXml(value));
    const commandUuid = crypto.randomUUID();
    const plist = '<?xml version="1.0" encoding="UTF-8"?>\n'
      + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
      + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n\t\t<key>Payload</key>\n\t\t<data>'
      + Buffer.from(profile, 'utf8').toString('base64')
      + '</data>\n\t\t<key>RequestType</key>\n\t\t<string>InstallProfile</string>\n\t</dict>\n\t<key>CommandUUID</key>\n\t<string>'
      + commandUuid + '</string>\n</dict>\n</plist>\n';
    out.push({ json: { skip: false, enrollment_id: device.enrollment_id, serial_number: device.serial_number, label: params.LABEL, command_uuid: commandUuid, plist } });
  }
}
return out;

const sent = $('Web-Link Befehle bauen').all().map((item) => item.json);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number || source.enrollment_id, label: source.label, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const failed = results.filter((row) => !row.queued);
const labels = [...new Set(results.map((row) => row.label))];
const serials = [...new Set(results.filter((row) => row.queued).map((row) => row.serial))];
const lines = [(results.length - failed.length) + ' von ' + results.length + ' Befehl(en) eingereiht. Web-Link(s): ' + labels.join(', ') + '. iPads: ' + (serials.join(', ') || 'keine') + '.'];
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.label + ' (' + row.detail + ')').join(', ') + '.');
lines.push('Der Web-Link erscheint auf dem Home-Bildschirm, sobald das iPad den Befehl abholt.');
return [{ json: { title: failed.length === 0 ? 'Web-Link wird installiert' : 'Web-Link mit Problemen', message: lines.join(' ') } }];

const crypto = require('crypto');
const input = $('Eingabe pruefen').first().json;
const rows = $('Deinstall Katalog lesen').all().map((item) => item.json).filter((row) => row.ref);
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
const skip = (message) => [{ json: { skip: true, title: 'Nichts deinstalliert', message } }];
if (devices.length === 0) return skip(input.alle ? 'Es ist noch kein iPad angemeldet.' : 'Keines der gewaehlten iPads ist angemeldet: ' + input.target + '.');
let targets = [];
if (input.mode === 'webclip') targets = rows.filter((row) => row.kind === 'web' && input.profiles.includes(row.key)).map((row) => ({ type: 'profile', label: row.name, ref: row.ref }));
if (input.mode === 'one') targets = rows.filter((row) => row.kind === 'app' && row.name === input.appName).map((row) => ({ type: 'app', label: row.name, ref: row.ref }));
if (input.mode === 'other') targets = rows.filter((row) => row.kind === 'app' && row.key === input.adamId).map((row) => ({ type: 'app', label: row.name, ref: row.ref }));
if (input.mode === 'webclip' ? targets.length !== input.profiles.length : targets.length === 0) return skip('Diese App oder dieser Web-Link steht nicht im Katalog und kann deshalb nicht gezielt deinstalliert werden.');
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (commandUuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + commandUuid + '</string>\n</dict>\n</plist>\n';
const out = [];
for (const device of devices) {
  for (const target of targets) {
    const commandUuid = crypto.randomUUID();
    const plist = head
      + '\t\t<key>Identifier</key>\n\t\t<string>' + escapeXml(target.ref) + '</string>\n'
      + '\t\t<key>RequestType</key>\n\t\t<string>' + (target.type === 'app' ? 'RemoveApplication' : 'RemoveProfile') + '</string>\n'
      + tail(commandUuid);
    out.push({ json: { skip: false, enrollment_id: device.enrollment_id, serial_number: device.serial_number, label: target.label, command_uuid: commandUuid, plist } });
  }
}
return out;

const sent = $('Deinstall Befehle bauen').all().map((item) => item.json);
const results = $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  return { serial: source.serial_number || source.enrollment_id, label: source.label, queued, detail: queued ? '' : String(response.json.statusCode || response.json.error || 'keine Antwort') };
});
const failed = results.filter((row) => !row.queued);
const labels = [...new Set(results.map((row) => row.label))];
const serials = [...new Set(results.filter((row) => row.queued).map((row) => row.serial))];
const lines = [(results.length - failed.length) + ' von ' + results.length + ' Befehl(en) eingereiht. Deinstalliert wird: ' + labels.join(', ') + '. iPads: ' + (serials.join(', ') || 'keine') + '.'];
if (failed.length > 0) lines.push('Nicht eingereiht: ' + failed.map((row) => row.serial + '/' + row.label + ' (' + row.detail + ')').join(', ') + '.');
lines.push('Die App verschwindet, sobald das iPad den Befehl abholt. Ist sie nicht installiert, passiert nichts.');
return [{ json: { title: failed.length === 0 ? 'Deinstallation gestartet' : 'Deinstallation mit Problemen', message: lines.join(' ') } }];
